package com.turboio.androidtests;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.lang.reflect.*;import java.net.*;import java.nio.file.*;import java.security.*;import java.util.*;import org.json.*;

/** Bounded current-account cache/file metadata audit. No HTTP, audio read,
 * playback, capture, original database edits or remote uploads. Global recording
 * preferences are explicitly not proof of current-account ownership. */
public final class LifelogAudioMetadataProbe extends Instrumentation {
 private ClassLoader loader;private String nonce,binding;private int visited;private boolean limited;
 private final Set<String> sources=new HashSet<>();private final Map<String,Set<String>> sourceTypes=new HashMap<>();private final Map<String,Integer> extensions=new TreeMap<>();private final JSONArray matches=new JSONArray();
 private Class<?> type(String n)throws Exception{return loader.loadClass("com.turboio.addon."+n);}
 private Object call(Object o,String n,Class<?>[] t,Object...a)throws Exception{Class<?> c=o instanceof Class?(Class<?>)o:o.getClass();Method m=c.getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(o instanceof Class?null:o,a);}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void check(boolean ok,String code){if(!ok)throw new IllegalStateException(code);}
 private String sha(String text)throws Exception{StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(text.getBytes("UTF-8")))s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 private Object parse(Object value)throws Exception{return value instanceof String?call(type("WireJson"),"read",new Class<?>[]{byte[].class},((String)value).getBytes("UTF-8")):value;}
 private Object login()throws Exception{return call(type("Host107Login"),"account",new Class<?>[0]);}
 private void admit()throws Exception{Object a=login();check(a!=null&&binding.equals(field(a,"binding")),"AUDIO_METADATA_ACCOUNT_CHANGED");}
 private JSONArray rows(Object raw)throws Exception{Object value=parse(raw);check(value instanceof List&&((List<?>)value).size()<=10000,"AUDIO_METADATA_LIST_SHAPE");JSONArray out=new JSONArray();for(Object r:(List<?>)value){check(r instanceof Map,"AUDIO_METADATA_ROW_SHAPE");Map<?,?> row=(Map<?,?>)r;JSONObject shape=new JSONObject();for(String key:new String[]{"id","taskId","recordingId","sessionId","bucketName","objectKey","audioSaveFlag","filePath","localPath","path","audioPath","duration","audioLengthSeconds"})if(row.containsKey(key)){Object v=row.get(key);shape.put(key,v==null?"null":v instanceof String?"string":v instanceof Number?"number":v instanceof Boolean?"boolean":"other");}
  JSONArray links=new JSONArray();for(String key:new String[]{"id","taskId","recordingId","sessionId"})if(sources.contains(row.get(key)))links.put(key);if(links.length()>0)shape.put("source_id_match_fields",links);out.put(shape);
 }return out;}
 private void scan(File file,File boundary,int depth)throws Exception{
  if(file==null||!file.exists()||depth>8)return;if(++visited>3000){limited=true;return;}
  File f=file.getCanonicalFile();if(!file.getAbsoluteFile().equals(f)||Files.isSymbolicLink(file.toPath())||!f.toPath().startsWith(boundary.toPath()))return;
  if(f.isDirectory()){String n=f.getName();if(Arrays.asList("logs","appLog","flutter_assets","databases","voice-drafts","agent-accounts","material-accounts","material-accounts-v2").contains(n))return;File[] children=f.listFiles();if(children!=null)for(File child:children){if(limited)break;scan(child,boundary,depth+1);}return;}
  String name=f.getName();int dot=name.lastIndexOf('.');if(dot<0)return;String ext=name.substring(dot+1).toLowerCase(Locale.ROOT);if(!Arrays.asList("m4a","wav","aac","ogg","opus","mp3","flac","pcm").contains(ext))return;
  extensions.put(ext,extensions.getOrDefault(ext,0)+1);for(String id:sources)if(name.equals(id)||name.startsWith(id+".")||name.equals("recording_"+id+"."+ext)){check(matches.length()<256,"AUDIO_METADATA_MATCH_BUDGET");matches.put(new JSONObject().put("source_id_sha256",sha(id)).put("path_sha256",sha(f.getPath())).put("bytes",f.length()).put("extension",ext).put("source_types",new JSONArray(sourceTypes.get(id))).put("parent_directory_kind",Arrays.asList("recording","recordings","audio","audios","opus","lifelog","always_on_cached_audio").contains(f.getParentFile().getName())?f.getParentFile().getName():"other").put("nonempty",f.length()>0).put("filename_match_only",true).put("association_verified",false));}
 }
 @Override public void onCreate(Bundle args){super.onCreate(args);nonce=args.getString("probe_id","");start();}
 @Override public void onStart(){Bundle result=new Bundle();JSONObject audit=new JSONObject();try{
  check(nonce.matches("[a-f0-9]{32}"),"AUDIO_METADATA_NONCE");Context target=getTargetContext();loader=target.getClassLoader();android.content.pm.PackageInfo pkg=target.getPackageManager().getPackageInfo(target.getPackageName(),0);check(pkg.getLongVersionCode()==10498&&"0.5.3-dev76".equals(pkg.versionName),"AUDIO_METADATA_VERSION");
  target.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName(target,"com.rayneo.venus.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Object account=null;long end=SystemClock.elapsedRealtime()+12000;do{account=login();if(account!=null)break;Thread.sleep(200);}while(SystemClock.elapsedRealtime()<end);check(account!=null,"OFFICIAL_LOGIN_REQUIRED");binding=(String)field(account,"binding");
  Map<String,?> settings=new HashMap<>(target.getSharedPreferences("io_agent_materials_v1",0).getAll());SharedPreferences pref=target.getSharedPreferences("FlutterSharedPreferences",0);Map<String,?> prefs=new HashMap<>(pref.getAll());
  Constructor<?> ctor=type("MaterialSettings").getDeclaredConstructor(Context.class);ctor.setAccessible(true);Object config=call(ctor.newInstance(target),"load",new Class<?>[0]);check(config!=null&&binding.equals(field(config,"account")),"AUDIO_METADATA_CONFIG");Object connection=field(config,"connection");File files=(File)call(type("MaterialSyncSession"),"accountFiles",new Class<?>[]{File.class,type("MaterialConfig")},target.getFilesDir(),config);File queue=new File(files,"material-outbox/"+call(connection,"binding",new Class<?>[0])+"/state.json");check(queue.isFile()&&!Files.isSymbolicLink(queue.toPath())&&queue.length()<=33554432,"AUDIO_METADATA_QUEUE");byte[] before=Files.readAllBytes(queue.toPath());
  File flutter=new File(target.getApplicationInfo().dataDir,"app_flutter");File cacheFile=(File)call(account,"cacheFile",new Class<?>[]{File.class},flutter);Map<?,?> cache=(Map<?,?>)call(loader.loadClass("com.turboio.androidtests.voice.OfficialMetadataCache"),"read",new Class<?>[]{File.class},cacheFile);check(cache.size()<=256,"AUDIO_METADATA_CACHE_BUDGET");
  // Source IDs are obtained only from this account's official events cache.
  Map<String,Integer> types=new TreeMap<>();for(Map.Entry<?,?> e:cache.entrySet()){URI u=new URI((String)e.getKey());if(!"/lifelog/api/v1/events".equals(u.getPath()))continue;Map<?,?> response=(Map<?,?>)parse(((Map<?,?>)parse(e.getValue())).get("response"));if(!Long.valueOf(0).equals(response.get("code")))continue;Object data=response.get("data");if(!(data instanceof Map))continue;Object events=((Map<?,?>)data).get("events");if(!(events instanceof List))continue;for(Object ev:(List<?>)events){Object info=((Map<?,?>)ev).get("transcriptionInfos");if(!(info instanceof List))continue;for(Object v:(List<?>)info){Map<?,?> link=(Map<?,?>)v;Object id=link.get("sourceId"),t=link.get("sourceType");check(id instanceof String&&((String)id).matches("[A-Za-z0-9_.:-]{1,128}"),"AUDIO_METADATA_SOURCE");sources.add((String)id);if(t instanceof String)sourceTypes.computeIfAbsent((String)id,k->new TreeSet<>()).add((String)t);if(t instanceof String&&((String)t).matches("[A-Za-z_]{1,32}"))types.put((String)t,types.getOrDefault((String)t,0)+1);}}}check(sources.size()<=10000,"AUDIO_METADATA_SOURCE_BUDGET");
  JSONArray sessions=new JSONArray();for(Map.Entry<?,?> e:cache.entrySet()){URI u=new URI((String)e.getKey());if(!Arrays.asList("/clsapi/aiTask/selectPage","/clsapi/aiTask/v2/selectPage").contains(u.getPath()))continue;Map<?,?> response=(Map<?,?>)parse(((Map<?,?>)parse(e.getValue())).get("response"));Object data=parse(response.get("data"));if(data instanceof Map){Object selected=null;int found=0;for(String k:new String[]{"rows","records","items","list"})if(((Map<?,?>)data).containsKey(k)){selected=((Map<?,?>)data).get(k);found++;}check(found==1,"AUDIO_METADATA_SESSION_SHAPE");data=selected;}sessions.put(new JSONObject().put("path",u.getPath()).put("rows",rows(data)));}
  JSONArray local=new JSONArray();for(String key:new String[]{"recording_cache_list","flutter.recording_cache_list","session_task_list","flutter.session_task_list"}){Object raw=prefs.get(key);JSONObject entry=new JSONObject().put("key",key).put("present",raw!=null).put("account_ownership_unverified",true);if(raw!=null){Object parsed=parse(raw);entry.put("type",parsed instanceof List?"array":parsed instanceof Map?"object":"other");if(parsed instanceof List)entry.put("rows",rows(parsed));}local.put(entry);}
  JSONArray cachedAudio=new JSONArray();File a4=new File(target.getFilesDir(),"always_on_cached_audio");if(a4.exists()){check(a4.isDirectory()&&!Files.isSymbolicLink(a4.toPath())&&a4.getCanonicalFile().getParentFile().equals(target.getFilesDir().getCanonicalFile()),"AUDIO_METADATA_CACHE_PATH");File[] audioFiles=a4.listFiles();check(audioFiles!=null&&audioFiles.length<=256,"AUDIO_METADATA_AUDIO_BUDGET");for(File f:audioFiles){check(f.isFile()&&!Files.isSymbolicLink(f.toPath())&&f.getCanonicalFile().getParentFile().equals(a4.getCanonicalFile()),"AUDIO_METADATA_CACHE_PATH");String name=f.getName(),id=name.endsWith(".opus")?name.substring(0,name.length()-5):"";cachedAudio.put(new JSONObject().put("filename_sha256",sha(name)).put("bytes",f.length()).put("opus_extension",name.endsWith(".opus")).put("source_id_match",sources.contains(id)).put("source_types",sourceTypes.containsKey(id)?new JSONArray(sourceTypes.get(id)):new JSONArray()));}}audit.put("always_on_cached_audio",cachedAudio).put("always_on_cached_audio_directory_present",a4.exists());
  for(File root:new File[]{target.getFilesDir(),flutter,target.getExternalFilesDir(null)})if(root!=null){File canonical=root.getCanonicalFile();scan(canonical,canonical,0);}admit();check(Arrays.equals(before,Files.readAllBytes(queue.toPath()))&&settings.equals(target.getSharedPreferences("io_agent_materials_v1",0).getAll())&&prefs.equals(pref.getAll()),"AUDIO_METADATA_STATE_CHANGED");
  audit.put("cache_entries",cache.size()).put("known_source_count",sources.size()).put("source_type_occurrences",new JSONObject(types)).put("cached_sessions",sessions).put("global_preferences",local).put("file_extensions",new JSONObject(extensions)).put("filename_matches",matches).put("file_scan_max_depth",8).put("file_scan_visited",visited).put("file_scan_limited",limited).put("association_verified",false);
  result.putBoolean("passed",true);result.putBoolean("state_unchanged",true);
 }catch(Throwable e){while(e.getCause()!=null)e=e.getCause();String message=e.getMessage();result.putBoolean("passed",false);result.putString("error",message!=null&&message.matches("[A-Z_]{3,90}")?message:e.getClass().getSimpleName());}result.putString("audit",audit.toString());result.putString("probe_id",nonce);result.putInt("network_requests",0);result.putBoolean("audio_read_or_capture",false);result.putBoolean("credentials_or_text_exported",false);finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
